/**
 * Where every figure comes from. The demo and a real pilot run through the same screens, so the
 * interface must always be able to say which numbers are real and which are simulated.
 *
 *   simulated  generated by the engine from the workspace profile (seeded, repeatable)
 *   curated    written by hand into the workspace (local calendar entries, menu, prices)
 *   imported   real records loaded from a till export or a POS connection
 *
 * Only sales and bookings can be imported today (see till.ts and csv.ts). Everything else stays
 * simulated or curated until a real integration replaces it; update `domains` when one does.
 */

import { isImported } from "./till";
import type { Workspace } from "./types";

export type Origin = "simulated" | "curated" | "imported";
export type Domain = "sales" | "bookings" | "reviews" | "weather" | "calendar" | "visibility" | "connectors";
export type DataMode = "demo" | "partial" | "live";

export const domainLabels: Record<Domain, string> = {
  sales: "Sales and till",
  bookings: "Bookings",
  reviews: "Reviews",
  weather: "Weather",
  calendar: "Local events and calendar",
  visibility: "Online visibility",
  connectors: "Connected apps",
};

export function provenance(ws: Workspace): Record<Domain, Origin> {
  const till: Origin = isImported(ws.id) ? "imported" : "simulated";
  return {
    sales: till,
    bookings: till,
    reviews: "simulated",
    weather: "simulated",
    calendar: "curated",
    visibility: "simulated",
    connectors: "simulated",
  };
}

export function dataMode(ws: Workspace): DataMode {
  const origins = Object.values(provenance(ws));
  const real = origins.filter((o) => o === "imported").length;
  if (real === 0) return "demo";
  return real === origins.length ? "live" : "partial";
}

/** Short label for the header. Never says "live" unless every domain is real. */
export function dataLabel(ws: Workspace): string {
  const mode = dataMode(ws);
  if (mode === "demo") return "Demo data";
  if (mode === "partial") return "Your till · rest is demo data";
  return "Live data";
}

/** Domains a viewer should be told are not real yet, for a "what is simulated" list. */
export function simulatedDomains(ws: Workspace): Domain[] {
  const p = provenance(ws);
  return (Object.keys(p) as Domain[]).filter((d) => p[d] !== "imported");
}
